import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.2Gs1zKBA.js";const b=JSON.parse('{"title":"A1 机械臂参数","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/editions.md","filePath":"getting-started/editions.md","lastUpdated":1793694501000}'),o={name:"getting-started/editions.md"};function h(c,t,s,i,n,l){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="a1-机械臂参数" tabindex="-1">A1 机械臂参数 <a class="header-anchor" href="#a1-机械臂参数" aria-label="Permalink to &quot;A1 机械臂参数&quot;">​</a></h1><p>本页整理 Onero A1 机械臂的主要技术参数，供选型、安装和控制参数配置时参考。</p><p>表格中的参数用于建立初始配置和检查范围，不能替代具体设备的铭牌、出厂资料或现场测试。控制程序中使用弧度、米时，应在输入边界处完成单位转换，避免把角度制参数直接传给 API。</p><div class="warning custom-block"><p class="custom-block-title">参数与安全说明</p><p>实际使用前请以设备铭牌、出厂资料和现场安全评估为准。负载、运动范围和速度参数不是安全操作许可，真机运行前必须确认机械臂固定可靠、工作区域无人员和障碍物，并确保供电可以随时切断。</p></div><h2 id="整机参数" tabindex="-1">整机参数 <a class="header-anchor" href="#整机参数" aria-label="Permalink to &quot;整机参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>数值</th></tr></thead><tbody><tr><td>型号</td><td>A1</td></tr><tr><td>自由度</td><td>7 轴</td></tr><tr><td>自重</td><td>4.3 kg</td></tr><tr><td>负载</td><td>≥ 3 kg</td></tr><tr><td>最大臂展</td><td>713.55 mm</td></tr><tr><td>重复定位精度</td><td>±0.1 mm</td></tr><tr><td>电源需求</td><td>48 V，电流 ≥7 A</td></tr><tr><td>接口</td><td>CAN 2.0，1 Mbps</td></tr><tr><td>功率</td><td>峰值 300 W</td></tr><tr><td>力反馈和碰撞检测</td><td>有</td></tr><tr><td>控制接口</td><td>位置控制、力控制</td></tr></tbody></table><h2 id="关节参数" tabindex="-1">关节参数 <a class="header-anchor" href="#关节参数" aria-label="Permalink to &quot;关节参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关节</th><th>运动范围</th><th>最大速度</th><th>额定扭矩</th><th>峰值扭矩</th></tr></thead><tbody><tr><td>J1</td><td>-60° 至 180°</td><td>180°/s</td><td>15 N·m</td><td>30 N·m</td></tr><tr><td>J2</td><td>-180° 至 15°</td><td>180°/s</td><td>15 N·m</td><td>30 N·m</td></tr><tr><td>J3</td><td>±158°</td><td>180°/s</td><td>15 N·m</td><td>30 N·m</td></tr><tr><td>J4</td><td>±110°</td><td>180°/s</td><td>15 N·m</td><td>30 N·m</td></tr><tr><td>J5</td><td>±158°</td><td>180°/s</td><td>3 N·m</td><td>7 N·m</td></tr><tr><td>J6</td><td>±90°</td><td>180°/s</td><td>3 N·m</td><td>7 N·m</td></tr><tr><td>J7</td><td>±158°</td><td>180°/s</td><td>3 N·m</td><td>7 N·m</td></tr></tbody></table><p>SDK 中的角度和角速度通常使用弧度制，分别为 <code>rad</code> 和 <code>rad/s</code>；本页表格保留技术参数资料中的角度制表示。API 使用方式请参阅<a href="/onerobot-A1/motion/">运动控制接口总览</a>。</p><h2 id="参数如何用于配置" tabindex="-1">参数如何用于配置 <a class="header-anchor" href="#参数如何用于配置" aria-label="Permalink to &quot;参数如何用于配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置任务</th><th>应参考的参数</th><th>进一步检查</th></tr></thead><tbody><tr><td>选择模型</td><td>A1L/A1R 和安装方向</td><td><code>mounting</code>、左右臂映射和 CAN 通道</td></tr><tr><td>设置关节目标</td><td>运动范围和最大速度</td><td>目标是否接近限位、速度和加速度是否过高</td></tr><tr><td>设置负载</td><td>负载和重心信息</td><td>工具、工件和安装姿态的实际变化</td></tr><tr><td>配置电源与通信</td><td>电源、CAN 速率和接口</td><td>设备说明、适配器驱动和总线状态</td></tr></tbody></table><p>任何“最大”参数都不应直接作为程序默认值。首次运动应从更小的范围和更低的速度开始，并在现场确认机械支撑、工具和工作空间。</p><h2 id="单位与配置边界" tabindex="-1">单位与配置边界 <a class="header-anchor" href="#单位与配置边界" aria-label="Permalink to &quot;单位与配置边界&quot;">​</a></h2><p>技术参数表使用设备资料中常见的角度制和毫米制，而 SDK 运动接口通常使用 SI 单位。将参数写入代码前，应在输入边界完成一次明确的转换：</p><table tabindex="0"><thead><tr><th>资料中的单位</th><th>SDK 常用单位</th><th>换算</th></tr></thead><tbody><tr><td>角度 <code>deg</code></td><td>关节角 <code>rad</code></td><td><code>rad = deg × π / 180</code></td></tr><tr><td>角速度 <code>deg/s</code></td><td><code>rad/s</code></td><td><code>rad/s = deg/s × π / 180</code></td></tr><tr><td>长度 <code>mm</code></td><td><code>m</code></td><td><code>m = mm / 1000</code></td></tr><tr><td>质量 <code>g</code></td><td><code>kg</code></td><td><code>kg = g / 1000</code></td></tr></tbody></table><p>关节范围、最大速度和扭矩只能用于初步检查目标是否明显不合理，不能代替针对工具、负载、姿态和环境的轨迹验证。接近限位或最大参数的任务应在仿真和低速条件下逐步确认。</p>',16)])])}const p=d(o,[["render",h]]);export{b as __pageData,p as default};
